/**
 * The lines of a cart as a table or as cards: product, variant, price, quantity, line total and a remove button.
 * Axes: layout (table, cards), media (image, none), density, tone.
 */
import { type ReactNode } from "react";
import { Button } from "../primitives/button/button";
import { Card } from "../primitives/card/card";
import { CardContent } from "../primitives/card/card-content";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { CartTable } from "../components/cart-table";
import { MediaFrame } from "../components/media-frame";
import { NumberField } from "../components/number-field";
import { SectionFrame } from "../components/section-frame";
import { fmtMoney, tpl } from "../utils";
import type { CartLine, CartLabels } from "./cart-list.types";

export type CartListProps = {
  id: string;
  title: string;
  lines: CartLine[];
  labels: CartLabels;
  layout?: "table" | "cards";
  media?: "image" | "none";
  tone?: "default" | "muted";
  density?: "default" | "compact";
  landmarkLabel?: string;
  onRemove?: (id: string) => void;
};

export function CartList({
  id,
  title,
  lines,
  labels,
  layout = "table",
  media = "image",
  tone = "default",
  density = "default",
  landmarkLabel,
  onRemove,
}: CartListProps) {
  return (
    <SectionFrame id={id} title={title} tone={tone} density={density} landmarkLabel={landmarkLabel}>
      {((layout as string) === "table") ? (
        <CartTable
          field={tpl("{0}-qty", id)}
          lines={lines}
          labels={labels}
          media={media}
          density={density}
          onRemove={(arg: string) => onRemove?.(arg)}
        />
      ) : (
        <Stack gap="4" align="stretch" data-testid="cart-cards">
          {(lines ?? []).map((line) => (
            <Card key={line.id} variant="default" data-testid="item">
              <CardContent className="flex flex-wrap items-center gap-4">
                {((media as string) === "image") ? (
                  <MediaFrame alt={line.name} ratio="1/1" className="size-16 shrink-0" />
                ) : null}
                <Stack gap="0" className="min-w-40 flex-1">
                  <Text size="sm" weight="semibold">
                    {line.name}
                  </Text>
                  <Text size="xs" className="text-muted-foreground">
                    {line.variant}
                  </Text>
                  <Text size="sm">
                    {fmtMoney(line.price, line.currency)}
                  </Text>
                </Stack>
                <NumberField
                  value={(line.qty == null ? undefined : String(line.qty))}
                  name={tpl("{0}-qty-{1}", id, line.id)}
                  min="1"
                  label={labels.qty}
                  decrease={labels.decrease}
                  increase={labels.increase}
                />
                <Text size="base" weight="bold">
                  {fmtMoney((line.price * line.qty), line.currency)}
                </Text>
                <Button
                  variant="ghost"
                  size="sm"
                  layout="icon"
                  aria-label={labels.remove}
                  data-testid="remove"
                  onClick={() => onRemove?.(line.id)}
                >
                  <LucideIcon name="x" size={16} />
                </Button>
              </CardContent>
            </Card>
          ))}
        </Stack>
      )}
    </SectionFrame>
  );
}

