export type CartLine = {
  id: string;
  name: string;
  variant: string;
  price: number;
  currency: string;
  qty: number;
};

export type CartLabels = {
  caption: string;
  product: string;
  price: string;
  qty: string;
  total: string;
  remove: string;
  subtotal: string;
  checkout: string;
  decrease: string;
  increase: string;
};
